CREATE TABLE "chat_messages" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "chat_messages_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"conversation_id" bigint NOT NULL,
	"sender" text NOT NULL,
	"staff_user_id" bigint,
	"customer_user_id" bigint,
	"body" text NOT NULL,
	"buttons" jsonb,
	"button_id" text,
	"flow_node" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chat_messages_sender" CHECK ("chat_messages"."sender" IN ('CUSTOMER', 'BOT', 'STAFF')),
	CONSTRAINT "chat_messages_body" CHECK (char_length("chat_messages"."body") BETWEEN 1 AND 2000),
	CONSTRAINT "chat_messages_staff" CHECK (("chat_messages"."sender" = 'STAFF') = ("chat_messages"."staff_user_id" IS NOT NULL)),
	CONSTRAINT "chat_messages_customer" CHECK (("chat_messages"."sender" = 'CUSTOMER') = ("chat_messages"."customer_user_id" IS NOT NULL)),
	CONSTRAINT "chat_messages_buttons" CHECK ("chat_messages"."buttons" IS NULL OR ("chat_messages"."sender" = 'BOT' AND jsonb_typeof("chat_messages"."buttons") = 'array')),
	CONSTRAINT "chat_messages_button_id" CHECK ("chat_messages"."button_id" IS NULL OR ("chat_messages"."sender" = 'CUSTOMER' AND char_length("chat_messages"."button_id") BETWEEN 1 AND 64)),
	CONSTRAINT "chat_messages_flow_node" CHECK ("chat_messages"."flow_node" IS NULL OR ("chat_messages"."sender" = 'BOT' AND char_length("chat_messages"."flow_node") BETWEEN 1 AND 64))
);
